<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Nine Decades of Oscar-Winning Scores: A Historical Trend Analysis (1934–2026)</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.7/dist/chart.umd.min.js"></script>
<style>
  :root {
    --gold: #d4a843;
    --gold-light: #f0d68a;
    --gold-dark: #a07e2e;
    --navy: #0f1b2d;
    --navy-mid: #1a2d47;
    --navy-light: #263d5e;
    --slate: #8a9bb5;
    --cream: #f5f0e8;
    --white: #ffffff;
    --text: #1a1a2e;
    --text-light: #4a4a6a;
    --text-muted: #7a7a9a;
    --accent-red: #c0392b;
    --accent-teal: #1abc9c;
    --accent-blue: #2980b9;
    --shadow: 0 2px 12px rgba(0,0,0,0.08);
    --shadow-lg: 0 8px 32px rgba(0,0,0,0.12);
    --radius: 8px;
    --radius-lg: 16px;
  }

  * { margin: 0; padding: 0; box-sizing: border-box; }

  body {
    font-family: 'Georgia', 'Times New Roman', serif;
    color: var(--text);
    background: var(--cream);
    line-height: 1.7;
    -webkit-font-smoothing: antialiased;
  }

  .header {
    background: linear-gradient(135deg, var(--navy) 0%, var(--navy-mid) 50%, var(--navy-light) 100%);
    color: var(--white);
    padding: 60px 40px 50px;
    text-align: center;
    position: relative;
    overflow: hidden;
  }
  .header::before {
    content: '';
    position: absolute;
    top: -50%;
    left: -50%;
    width: 200%;
    height: 200%;
    background: radial-gradient(ellipse at center, rgba(212,168,67,0.08) 0%, transparent 70%);
    pointer-events: none;
  }
  .header h1 {
    font-size: 2.4em;
    font-weight: 700;
    letter-spacing: -0.5px;
    margin-bottom: 12px;
    position: relative;
  }
  .header h1 span { color: var(--gold); }
  .header .subtitle {
    font-size: 1.1em;
    color: var(--slate);
    font-style: italic;
    max-width: 680px;
    margin: 0 auto;
    position: relative;
  }
  .header .meta {
    margin-top: 20px;
    font-size: 0.85em;
    color: var(--slate);
    position: relative;
  }

  .container {
    max-width: 1100px;
    margin: 0 auto;
    padding: 0 24px;
  }

  /* KPI Cards */
  .kpi-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 20px;
    margin: -30px 0 40px;
    position: relative;
    z-index: 2;
  }
  .kpi-card {
    background: var(--white);
    border-radius: var(--radius-lg);
    padding: 28px 20px;
    text-align: center;
    box-shadow: var(--shadow-lg);
    border-top: 4px solid var(--gold);
    transition: transform 0.2s;
  }
  .kpi-card:hover { transform: translateY(-3px); }
  .kpi-value {
    font-size: 2.6em;
    font-weight: 700;
    color: var(--navy);
    line-height: 1.1;
    margin-bottom: 6px;
  }
  .kpi-label {
    font-size: 0.85em;
    color: var(--text-muted);
    font-family: 'Helvetica Neue', Arial, sans-serif;
    text-transform: uppercase;
    letter-spacing: 0.5px;
  }

  /* Sections */
  .section {
    background: var(--white);
    border-radius: var(--radius-lg);
    padding: 40px;
    margin-bottom: 32px;
    box-shadow: var(--shadow);
  }
  .section h2 {
    font-size: 1.65em;
    color: var(--navy);
    margin-bottom: 8px;
    padding-bottom: 12px;
    border-bottom: 3px solid var(--gold);
    display: inline-block;
  }
  .section h3 {
    font-size: 1.2em;
    color: var(--navy-mid);
    margin: 24px 0 10px;
  }
  .section p {
    color: var(--text-light);
    margin-bottom: 14px;
    font-size: 0.98em;
    max-width: 900px;
  }
  .section .highlight {
    color: var(--gold-dark);
    font-weight: 700;
  }

  /* Top Composers Table */
  .composer-table {
    width: 100%;
    border-collapse: collapse;
    margin: 20px 0;
    font-family: 'Helvetica Neue', Arial, sans-serif;
    font-size: 0.92em;
  }
  .composer-table th {
    background: var(--navy);
    color: var(--white);
    padding: 12px 16px;
    text-align: left;
    font-weight: 600;
    letter-spacing: 0.3px;
  }
  .composer-table td {
    padding: 11px 16px;
    border-bottom: 1px solid #e8e4dd;
  }
  .composer-table tr:nth-child(even) { background: #faf8f4; }
  .composer-table tr:hover { background: #f0ece4; }
  .rank-badge {
    display: inline-block;
    width: 28px;
    height: 28px;
    border-radius: 50%;
    text-align: center;
    line-height: 28px;
    font-weight: 700;
    font-size: 0.85em;
    color: var(--white);
  }
  .rank-1 { background: var(--gold); }
  .rank-2 { background: #a0a0a0; }
  .rank-3 { background: #b87333; }
  .rank-default { background: var(--navy-light); }

  .win-bar-container {
    display: flex;
    align-items: center;
    gap: 8px;
  }
  .win-bar {
    height: 22px;
    background: linear-gradient(90deg, var(--gold), var(--gold-dark));
    border-radius: 4px;
    min-width: 20px;
  }
  .win-count {
    font-weight: 700;
    color: var(--navy);
    font-size: 0.95em;
  }

  /* Charts */
  .chart-wrap {
    position: relative;
    margin: 24px 0;
    width: 100%;
  }
  .chart-wrap canvas {
    width: 100% !important;
    max-height: 400px;
  }

  /* Era cards */
  .era-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 20px;
    margin: 20px 0;
  }
  .era-card {
    border-radius: var(--radius);
    padding: 24px;
    position: relative;
    overflow: hidden;
  }
  .era-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0;
    width: 5px;
    height: 100%;
  }
  .era-golden { background: #fdf6e3; }
  .era-golden::before { background: var(--gold); }
  .era-silver { background: #f0f4f8; }
  .era-silver::before { background: var(--accent-blue); }
  .era-modern { background: #f0faf5; }
  .era-modern::before { background: var(--accent-teal); }
  .era-contemporary { background: #fdf0ef; }
  .era-contemporary::before { background: var(--accent-red); }
  .era-card h4 {
    font-size: 1.1em;
    color: var(--navy);
    margin-bottom: 4px;
  }
  .era-card .era-range {
    font-size: 0.82em;
    color: var(--text-muted);
    font-family: 'Helvetica Neue', Arial, sans-serif;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: 10px;
  }
  .era-card p {
    font-size: 0.9em;
    color: var(--text-light);
    line-height: 1.6;
  }
  .era-card .era-stat {
    margin-top: 10px;
    font-family: 'Helvetica Neue', Arial, sans-serif;
    font-size: 0.82em;
    color: var(--text-muted);
    padding-top: 8px;
    border-top: 1px dashed #d0ccc4;
  }

  /* Milestones */
  .milestone-list {
    list-style: none;
    margin: 16px 0;
    padding: 0;
  }
  .milestone-list li {
    padding: 14px 16px 14px 52px;
    position: relative;
    border-bottom: 1px solid #ece8e0;
    font-size: 0.94em;
    color: var(--text-light);
  }
  .milestone-list li:last-child { border-bottom: none; }
  .milestone-list li::before {
    content: attr(data-year);
    position: absolute;
    left: 0;
    top: 14px;
    font-family: 'Helvetica Neue', Arial, sans-serif;
    font-size: 0.78em;
    font-weight: 700;
    color: var(--gold-dark);
    background: #faf5ea;
    padding: 2px 6px;
    border-radius: 4px;
