  /* Takeaways */
  .takeaway-list {
    list-style: none;
    padding: 0;
    counter-reset: takeaway;
  }
  .takeaway-list li {
    counter-increment: takeaway;
    padding: 16px 16px 16px 60px;
    position: relative;
    margin-bottom: 12px;
    background: #faf8f4;
    border-radius: var(--radius);
    font-size: 0.95em;
    color: var(--text-light);
    line-height: 1.6;
  }
  .takeaway-list li::before {
    content: counter(takeaway);
    position: absolute;
    left: 16px;
    top: 16px;
    width: 30px;
    height: 30px;
    border-radius: 50%;
    background: var(--navy);
    color: var(--gold);
    text-align: center;
    line-height: 30px;
    font-family: 'Helvetica Neue', Arial, sans-serif;
    font-weight: 700;
    font-size: 0.9em;
  }

  /* Decade table */
  .decade-table {
    width: 100%;
    border-collapse: collapse;
    margin: 20px 0;
    font-family: 'Helvetica Neue', Arial, sans-serif;
    font-size: 0.9em;
  }
  .decade-table th {
    background: var(--navy);
    color: var(--white);
    padding: 10px 14px;
    text-align: center;
    font-weight: 600;
  }
  .decade-table th:first-child { text-align: left; }
  .decade-table td {
    padding: 10px 14px;
